  "factions[faction-hxh-zoldyck].localizedName": "Familia Zoldyck",
  "factions[faction-hxh-zoldyck].description": "La familia de asesinos profesionales más temida del mundo, que reside en la montaña Kukuroo.",
  "factions[faction-hxh-zoldyck].longDescription": "Generaciones de asesinos entrenados desde su nacimiento. Entre sus miembros están el patriarca Zeno, el padre Silva, la madre Kikyo y los hijos, entre ellos Killua.",
  "factions[faction-hxh-zoldyck].structure[0].name": "Familia",
  "factions[faction-hxh-zoldyck].structure[0].members[0].role": "bisabuelo",
  "factions[faction-hxh-zoldyck].structure[0].members[1].role": "abuelo",
