  "factions[faction-hxh-zoldyck].structure[1].name": "Hijos",
  "factions[faction-hxh-zoldyck].structure[1].members[2].role": "heredero designado",
  "factions[faction-hxh-kurta].localizedName": "Clan Kurta",
  "factions[faction-hxh-kurta].description": "El clan de los Ojos Escarlata, masacrado por la Brigada Fantasma. Kurapika es su último superviviente conocido.",
  "factions[faction-hxh-kurta].longDescription": "Un pueblo aislado cuyos ojos se vuelven escarlata con las emociones intensas, considerados uno de los tesoros más valiosos del mundo.",
  "factions[faction-hxh-kakin-royal].localizedName": "Familia real de Kakin",
  "factions[faction-hxh-kakin-royal].description": "Los catorce príncipes de Kakin, que luchan por la sucesión al trono durante el viaje al Continente Oscuro.",
  "factions[faction-hxh-phantom-troupe].localizedName": "Brigada Fantasma (Genei Ryodan)",
  "factions[faction-hxh-phantom-troupe].description": "Banda de ladrones y asesinos de clase A procedente de Ciudad Meteoro. Trece miembros marcados por una araña.",
  "factions[faction-hxh-phantom-troupe].longDescription": "Fundada y dirigida por Chrollo Lucilfer, la Brigada masacró al clan Kurta por sus Ojos Escarlata. Cada miembro lleva un número y el tatuaje de la araña.",
  "factions[faction-hxh-phantom-troupe].structure[0].name": "Cabeza",
  "factions[faction-hxh-phantom-troupe].structure[0].members[0].role": "n.º 0",
